import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"腾讯混元术语表","description":"不教操作。先分清 Hy、TokenHub、元宝、CodeBuddy，再处理两套云文档和三套思考字段。","frontmatter":{"title":"腾讯混元术语表","description":"不教操作。先分清 Hy、TokenHub、元宝、CodeBuddy，再处理两套云文档和三套思考字段。","domain":"product","tags":["hunyuan","llm-api"],"role":"glossary"},"headers":[],"relativePath":"zh/products/hunyuan/hunyuan-glossary.md","filePath":"zh/products/hunyuan/hunyuan-glossary.md","lastUpdated":1787110548000}'),o={name:"zh/products/hunyuan/hunyuan-glossary.md"};function d(h,t,u,c,l,s){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="腾讯混元术语表" tabindex="-1">腾讯混元术语表 <a class="header-anchor" href="#腾讯混元术语表" aria-label="Permalink to &quot;腾讯混元术语表&quot;">​</a></h1><p>不教操作，只解释「为什么会撞名」。选门看 <a href="./">学习地图</a>。</p><h2 id="hy-混元" tabindex="-1">Hy / 混元 <a class="header-anchor" href="#hy-混元" aria-label="Permalink to &quot;Hy / 混元&quot;">​</a></h2><p><strong>是什么</strong>：腾讯自研大模型家族的现行品牌。官网 <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a> 与 <a href="https://hy.tencent.com/" target="_blank" rel="noreferrer">hy.tencent.com</a> 是同一站。国际通稿写过「Tencent Hy, formerly known as Tencent Hunyuan」。</p><p><strong>不是什么</strong>：不是元宝 App，不是 TokenHub 账号，不是一个可执行文件。</p><p>仓库、论文、老云产品仍大量使用 Hunyuan。写文档时两种叫法都要能对上官方页，不要发明第三种「混元 3.0」当产品名——当前旗舰语言模型官方名是 <strong>Hy3</strong>。</p><p>机制（为什么是 MoE、MTP 是什么）见 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>，本页不展开。</p><h2 id="hy3" tabindex="-1">Hy3 <a class="header-anchor" href="#hy3" aria-label="Permalink to &quot;Hy3&quot;">​</a></h2><p><strong>是什么</strong>：2026-07-06 正式发布的旗舰语言模型。TokenHub slug <code>hy3</code>。开源权重 <a href="https://github.com/Tencent-Hunyuan/Hy3" target="_blank" rel="noreferrer">Tencent-Hunyuan/Hy3</a>：295B 总参数、21B 激活、256K 上下文、Apache-2.0。</p><p>托管侧能力（<a href="https://cloud.tencent.com/document/product/1823/130051" target="_blank" rel="noreferrer">模型列表</a>）：深度思考（保留式）、结构化输出、Function Calling、Cache。产品页补充了 Coding / 长文 / Agent。</p><p><strong>不是什么</strong>：</p><ul><li>不是 <code>hy3-preview</code>。Preview 官方标注 2026-08-31 下线。</li><li>不是「混元生图 / 生视频 / 生 3D」那些模态模型。</li><li>不是 CodeBuddy 里的某一个按钮。</li></ul><h2 id="tokenhub" tabindex="-1">TokenHub <a class="header-anchor" href="#tokenhub" aria-label="Permalink to &quot;TokenHub&quot;">​</a></h2><p><strong>是什么</strong>：腾讯云「大模型服务平台」。文档树产品 ID <strong>1823</strong>。官方概述：统一入口，<strong>整合混元并引入第三方模型</strong>。调混元只是它的一条线。</p><p><strong>为什么单独成词</strong>：2026 年 Hy3 的调用指南、价格、Key、Claude Code 接入都写在这棵树上。把它理解成「混元控制台」会漏掉「它还卖别人的模型」，也会和 1729 老树打架。</p><p>鉴权是 TokenHub 自己的 API Key，不是随便一个腾讯云 SecretId/SecretKey。</p><h2 id="两套云文档" tabindex="-1">两套云文档 <a class="header-anchor" href="#两套云文档" aria-label="Permalink to &quot;两套云文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>树</th><th>ID</th><th>现在怎么用</th></tr></thead><tbody><tr><td>TokenHub</td><td>1823</td><td><strong>本站主源</strong>。Hy3、价格、OpenAI 兼容口</td></tr><tr><td>腾讯混元大模型</td><td>1729</td><td>仍在线。页面上还能看到 Hunyuan-T1 / TurboS 等更早规格</td></tr></tbody></table><p><a href="https://cloud.tencent.com/product/hunyuan" target="_blank" rel="noreferrer">cloud.tencent.com/product/hunyuan</a> 抓下来仍偏老规格；同主题的 <a href="https://cloud.tencent.com/product/tclm" target="_blank" rel="noreferrer">product/tclm</a> 已切到 Hy3。两份营销页不一致时，<strong>以 TokenHub 文档 + hunyuan.tencent.com 为准</strong>，并在正文点名冲突。</p><h2 id="思考档位为什么有三套词" tabindex="-1">思考档位为什么有三套词 <a class="header-anchor" href="#思考档位为什么有三套词" aria-label="Permalink to &quot;思考档位为什么有三套词&quot;">​</a></h2><p>不是三个产品，是三份官方页用了不同 JSON：</p><table tabindex="0"><thead><tr><th>出处</th><th>怎么写</th></tr></thead><tbody><tr><td>TokenHub 调用指南</td><td><code>thinking: { type: &quot;enabled&quot; }</code>；<code>reasoning_effort</code>（<code>hy3</code> 默认 <code>low</code>）</td></tr><tr><td>tclm 产品页</td><td><code>no_think</code> / <code>think_low</code> / <code>think_high</code></td></tr><tr><td>Hy3 开源 README</td><td><code>extra_body.chat_template_kwargs.reasoning_effort = no_think | low | high</code>（默认 <code>no_think</code>）</td></tr></tbody></table><p>本站不猜「TokenHub 的 low 等于开源的哪一档」。照你正在打的那份文档抄字段。带 <code>tools</code> 时 TokenHub 会把 <code>low</code> 映射成 <code>high</code>（调用指南原文）。</p><h2 id="同厂产品不是混元" tabindex="-1">同厂产品不是混元 <a class="header-anchor" href="#同厂产品不是混元" aria-label="Permalink to &quot;同厂产品不是混元&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名字</th><th>官方一句话 / 定位</th><th>入口</th><th>本站</th></tr></thead><tbody><tr><td>元宝</td><td>「腾讯推出的全能 AI 助手，已接入最新的混元 Hy3 模型」</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a></td><td>#76</td></tr><tr><td>CodeBuddy</td><td>腾讯云代码助手（IDE / CLI）</td><td><a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">codebuddy.cn</a></td><td>#78</td></tr><tr><td>WorkBuddy</td><td>办公 Agent 工作台</td><td><a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">workbuddy.cn</a></td><td>地图一行</td></tr><tr><td>ima</td><td>「以知识库为基础的 AI 知识管家」</td><td><a href="https://ima.qq.com/" target="_blank" rel="noreferrer">ima.qq.com</a></td><td>地图一行</td></tr></tbody></table><p>它们<strong>消费</strong>混元（或其它模型），本身不是「混元开放能力」。Hy3 README 提到在 CodeBuddy / Cline / KiloCode 上评测，那是脚手架名字，不能反过来说混元 = CodeBuddy。</p><h2 id="开源名-vs-api-slug" tabindex="-1">开源名 vs API slug <a class="header-anchor" href="#开源名-vs-api-slug" aria-label="Permalink to &quot;开源名 vs API slug&quot;">​</a></h2><p>GitHub org <a href="https://github.com/Tencent-Hunyuan" target="_blank" rel="noreferrer">Tencent-Hunyuan</a> 的仓库名偏 Hunyuan*（HunyuanVideo、HunyuanImage-3.0、Hunyuan3D-2.1）。TokenHub 的调用参数偏 <code>hy-*</code> / <code>hy3</code>。</p><p>对账时以各页原文为准，禁止「看名字像就当成同一个 model 字段」。</p><h2 id="本站不写的机制" tabindex="-1">本站不写的机制 <a class="header-anchor" href="#本站不写的机制" aria-label="Permalink to &quot;本站不写的机制&quot;">​</a></h2><p>MoE 路由、MTP 推测解码、量化训练、RL 后训练流程：官方 README 有章节，但属于模型内部。需要原理时去 <a href="./../../tech/fundamentals/LLM.html">LLM 基础</a>。本目录只保留官方给出的<strong>规格数字和启动命令</strong>。</p>',31)])])}const m=e(o,[["render",d]]);export{g as __pageData,m as default};
